"use client";

import { useState } from "react";
import { Star, ExternalLink, Check, Smartphone, UserMinus, Loader2 } from "lucide-react";
import { formatDate, relativeTime, getInitial } from "@/lib/utils";
import type { InstagramUser } from "@/lib/types";
import type { ProfileContext } from "@/components/ProfileLogin";

interface UserRowProps {
  user: InstagramUser;
  isWhitelisted: boolean;
  isVisited: boolean;
  onToggleWhitelist: (username: string) => void;
  onMarkVisited: (username: string) => void;
  isSelected?: boolean;
  onToggleSelect?: (username: string) => void;
  showWhitelist?: boolean;
  badge?: { label: string; color: string } | null;
  profile?: ProfileContext | null;
  onOpenProfileModal?: (user: InstagramUser) => void;
  onActionSuccess?: (username: string, action: "unfollow" | "follow") => void;
}

export default function UserRow({
  user,
  isWhitelisted,
  isVisited,
  onToggleWhitelist,
  onMarkVisited,
  isSelected,
  onToggleSelect,
  showWhitelist = true,
  badge,
  profile,
  onOpenProfileModal,
  onActionSuccess,
}: UserRowProps) {
  const [isUnfollowing, setIsUnfollowing] = useState(false);
  const [isUnfollowed, setIsUnfollowed] = useState(false);

  const hasSession = Boolean(profile?.sessionId && profile?.csrfToken);

  const handleOpenNativeApp = (e: React.MouseEvent) => {
    e.stopPropagation();
    onMarkVisited(user.username);
    const appUrl = `instagram://user?username=${user.username}`;
    const webUrl = user.href || `https://www.instagram.com/${user.username}/`;

    const start = Date.now();
    window.location.href = appUrl;

    setTimeout(() => {
      if (Date.now() - start < 1500) {
        window.open(webUrl, "_blank", "noopener,noreferrer");
      }
    }, 1200);
  };

  const handleAutomatedUnfollow = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // If not authenticated, open native mobile app directly
    if (!hasSession) {
      handleOpenNativeApp(e);
      return;
    }

    setIsUnfollowing(true);
    try {
      const res = await fetch("/api/instagram/action", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          targetUsername: user.username,
          action: "unfollow",
          sessionId: profile!.sessionId,
          csrfToken: profile!.csrfToken,
        }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        setIsUnfollowed(true);
        onMarkVisited(user.username);
        onActionSuccess?.(user.username, "unfollow");
      } else {
        // If API fails or blocked, fallback to opening app
        handleOpenNativeApp(e);
      }
    } catch {
      handleOpenNativeApp(e);
    } finally {
      setIsUnfollowing(false);
    }
  };

  return (
    <div
      onClick={() => onOpenProfileModal?.(user)}
      className={`flex items-center gap-3 px-3.5 py-2.5 rounded-xl transition-colors duration-150 group border border-transparent cursor-pointer ${
        isVisited || isUnfollowed
          ? "opacity-60 bg-zinc-50/60 dark:bg-white/[0.01]"
          : "hover:bg-zinc-50 dark:hover:bg-white/[0.03] hover:border-zinc-200/60 dark:hover:border-white/[0.04]"
      }`}
    >
      {/* Checkbox */}
      {onToggleSelect && (
        <input
          type="checkbox"
          checked={isSelected}
          onChange={(e) => {
            e.stopPropagation();
            onToggleSelect(user.username);
          }}
          className="w-3.5 h-3.5 rounded border-zinc-300 dark:border-zinc-700 text-purple-600 focus:ring-0 cursor-pointer shrink-0"
        />
      )}

      {/* Avatar */}
      <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-[#833ab4] via-[#fd1d1d] to-[#fcb045] text-white flex items-center justify-center text-xs font-bold shrink-0 shadow-xs">
        {getInitial(user.username)}
      </div>

      {/* Info */}
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs sm:text-sm font-semibold text-zinc-900 dark:text-zinc-100 truncate">
            @{user.username}
          </span>
          {isUnfollowed ? (
            <span className="inline-flex items-center gap-1 text-[10px] font-semibold text-rose-700 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/40 px-1.5 py-0.2 rounded-md shrink-0">
              <Check className="w-2.5 h-2.5" /> Unfollowed
            </span>
          ) : isVisited ? (
            <span className="inline-flex items-center gap-1 text-[10px] font-medium text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/40 px-1.5 py-0.2 rounded-md shrink-0">
              <Check className="w-2.5 h-2.5" /> Checked
            </span>
          ) : null}
          {badge && !isUnfollowed && (
            <span
              className={`text-[10px] font-medium px-1.5 py-0.2 rounded-md shrink-0 ${badge.color}`}
            >
              {badge.label}
            </span>
          )}
        </div>
        {user.timestamp > 0 && (
          <p
            className="text-[11px] text-zinc-400 mt-0.5"
            title={formatDate(user.timestamp)}
          >
            Connected {relativeTime(user.timestamp)}
          </p>
        )}
      </div>

      {/* Actions */}
      <div className="flex items-center gap-1.5 shrink-0" onClick={(e) => e.stopPropagation()}>
        {/* Whitelist Star */}
        {showWhitelist && (
          <button
            onClick={() => onToggleWhitelist(user.username)}
            className={`p-1.5 rounded-lg transition-colors cursor-pointer ${
              isWhitelisted
                ? "text-amber-500 bg-amber-50 dark:bg-amber-950/30"
                : "text-zinc-300 dark:text-zinc-600 hover:text-amber-500 hover:bg-amber-50/50 dark:hover:bg-amber-950/20"
            }`}
            title={isWhitelisted ? "Remove from whitelist" : "Add to whitelist"}
          >
            <Star
              className="w-3.5 h-3.5"
              fill={isWhitelisted ? "currentColor" : "none"}
            />
          </button>
        )}

        {/* 1-Click Unfollow Button (Automated if logged in, otherwise opens app) */}
        <button
          onClick={handleAutomatedUnfollow}
          disabled={isUnfollowing || isUnfollowed}
          className={`flex items-center gap-1 px-2.5 py-1 text-xs font-semibold rounded-lg transition-colors cursor-pointer ${
            isUnfollowed
              ? "text-zinc-400 bg-zinc-100 dark:bg-zinc-800 cursor-not-allowed"
              : "text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/40 hover:bg-rose-100 dark:hover:bg-rose-900/40 border border-rose-200/60 dark:border-rose-900/40"
          }`}
          title={hasSession ? "Unfollow automatically" : "Open & unfollow in Instagram"}
        >
          {isUnfollowing ? (
            <>
              <Loader2 className="w-3 h-3 animate-spin" />
              <span className="hidden sm:inline">Unfollowing...</span>
            </>
          ) : isUnfollowed ? (
            <>
              <Check className="w-3 h-3" />
              <span>Unfollowed</span>
            </>
          ) : (
            <>
              <UserMinus className="w-3 h-3" />
              <span>{hasSession ? "Unfollow" : "Unfollow"}</span>
            </>
          )}
        </button>

        {/* Fast Mobile Intent Button */}
        <button
          onClick={handleOpenNativeApp}
          className="flex items-center gap-1 p-1.5 rounded-lg text-zinc-400 hover:text-purple-600 dark:hover:text-purple-400 hover:bg-purple-50 dark:hover:bg-purple-950/30 transition-colors cursor-pointer"
          title="Open in Instagram App"
        >
          <Smartphone className="w-3.5 h-3.5" />
        </button>

        {/* Web Profile Link */}
        <a
          href={user.href || `https://www.instagram.com/${user.username}/`}
          target="_blank"
          rel="noopener noreferrer"
          onClick={() => onMarkVisited(user.username)}
          className="p-1.5 rounded-lg text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-200 hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
          title="Open Instagram Web"
        >
          <ExternalLink className="w-3.5 h-3.5" />
        </a>
      </div>
    </div>
  );
}
